constexpr std::float_epsilon = std::numeric_limits<float>::epsilon();
constexpr float epsilon_tolerance = 100.0f * std::float_epsilon;

// First compare by name
if (lhs_name != rhs_name) {
    return lhs_name < rhs_name;
}

// If names are equal, compare points
size_t min_size = std::min(lhs_points.size(), rhs_points.size());
for (size_t i = 0; i < min_size; ++i) {
    float diff = lhs_points[i] - rhs_points[i];
    if (std::abs(diff) > epsilon_tolerance) {
        return diff < 0.0f;
    }
}

// If all compared points are equal within tolerance, shorter vector is considered smaller
return lhs_points.size() < rhs_points.size();
